// boss_fill.cpp: a Logger interface, one real logger, and a counting lambda.
#include <iostream>
#include <memory>
#include <string>
#include <utility>

struct Logger {
    virtual void log(const std::string& msg) = 0;
    virtual ~Logger() = default;
};

struct ConsoleLogger : Logger {
    void log(const std::string& msg) override { std::cout << "[log] " << msg << '\n'; }
};

int main() {
    std::unique_ptr<Logger> logger = std::make_unique<ConsoleLogger>();
    auto report = [lg = std::move(logger), count = 0](const std::string& m) mutable {
        ++count;
        lg->log(std::to_string(count) + ": " + m);
    };
    report("door opened");
    report("lights on");
    std::cout << "logger is " << (logger ? "still here" : "inside the lambda") << '\n';
}

