#include <algorithm>
#include <iostream>
#include <memory>
#include <vector>

struct Shape {
    virtual double area() const = 0;
    virtual ~Shape() = default;
};
struct Sq : Shape {
    double s;
    explicit Sq(double s_) : s{s_} {}
    double area() const override { return s * s; }
};

int main() {
    std::vector<std::unique_ptr<Shape>> shapes;
    for (double s : {3.0, 1.0, 2.0}) shapes.push_back(std::make_unique<Sq>(s));
    double limit = shapes[1]->area();
    auto big = [limit](const std::unique_ptr<Shape>& p) { return p->area() > limit; };
    auto n = std::count_if(shapes.begin(), shapes.end(), big);
    std::cout << n << " shapes bigger than " << limit << '\n';
}

