// boss_predict.cpp: remotes, a shelf and a row of buttons.
#include <functional>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

struct Device {
    virtual std::string play() const { return "hum"; }
    virtual ~Device() = default;
};
struct Tv : Device {
    std::string play() const override { return "film"; }
};
struct Radio : Device {};

int main() {
    std::vector<std::unique_ptr<Device>> shelf;
    shelf.push_back(std::make_unique<Tv>());
    shelf.push_back(std::make_unique<Radio>());
    int presses{0};
    std::vector<std::function<std::string()>> buttons;
    for (const auto& d : shelf) {
        Device* p = d.get();
        buttons.push_back([p, &presses] { ++presses; return p->play(); });
    }
    std::string first_copy = buttons[0]();
    Device sliced = *shelf[0];
    std::cout << first_copy << ' ' << buttons[1]() << ' ' << sliced.play() << ' ' << presses << '\n';
}

