// boss_trace.cpp: counting gadgets that are alive in a box of remotes.
#include <iostream>
#include <memory>
#include <vector>

int alive{0};

struct Gadget {
    Gadget() { ++alive; }
    virtual ~Gadget() { --alive; }
    virtual int power() const { return 1; }
};
struct Drone : Gadget {
    int power() const override { return 5; }
};

int main() {
    std::vector<std::unique_ptr<Gadget>> box;
    int total{0};
    for (int round = 1; round <= 4; ++round) {
        if (round % 2 == 1) box.push_back(std::make_unique<Drone>());
        else box.push_back(std::make_unique<Gadget>());
        if (round == 3) box.erase(box.begin());      // recycle the oldest
        Gadget spare;
        total += box.back()->power();
        std::cout << round << ' ' << box.back()->power() << ' ' << total << ' ' << alive << '\n';
    }
}

