// composition.cpp: a Car HAS AN Engine; it isn't one.
#include <iostream>
#include <string>
#include <utility>

class Engine {
public:
    void start() { running_ = true; std::cout << "  engine: vroom\n"; }
    bool running() const { return running_; }
private:
    bool running_{false};
};

class Car {
public:
    explicit Car(std::string name) : name_{std::move(name)} {}
    void drive() {
        std::cout << name_ << " wants to drive\n";
        if (!engine_.running()) engine_.start();   // the car uses its engine
        std::cout << name_ << " is moving\n";
    }
private:
    std::string name_;
    Engine engine_;          // a member, not a base class
};

int main() {
    Car car{"Wren's van"};
    car.drive();
    car.drive();
