// devices.cpp: one base class, two derived classes that reuse it.
#include <iostream>
#include <string>
#include <utility>

class Device {
public:
    explicit Device(std::string name) : name_{std::move(name)} {}
    void power_on() { std::cout << name_ << " is on\n"; }
    const std::string& name() const { return name_; }
private:
    std::string name_;
};

class Tv : public Device {           // a Tv IS A Device, plus a channel
public:
    explicit Tv(std::string name) : Device{std::move(name)} {}
    void set_channel(int c) { channel_ = c; std::cout << name() << " on channel " << channel_ << '\n'; }
private:
    int channel_{1};
};

class Radio : public Device {        // a Radio IS A Device, plus a station
public:
    explicit Radio(std::string name) : Device{std::move(name)} {}
    void tune(double mhz) { std::cout << name() << " tuned to " << mhz << " MHz\n"; }
};

int main() {
    Tv tv{"Lounge TV"};
    Radio radio{"Kitchen radio"};
    tv.power_on();          // inherited from Device
    tv.set_channel(4);      // Tv's own
    radio.power_on();       // inherited from Device
    radio.tune(98.5);       // Radio's own
}

