// func_ptr.cpp: the old C way: a pointer to a function.
#include <iostream>

int square(int x) { return x * x; }
int negate(int x) { return -x; }

int apply(int (*f)(int), int value) { return f(value); }   // f is a function pointer

int main() {
    int (*button)(int) = square;          // point at square
    std::cout << button(5) << '\n';
    button = negate;                      // re-point at negate
    std::cout << button(5) << '\n';
    std::cout << apply(square, 9) << '\n';
    std::cout << apply([](int x) { return x + 1; }, 9) << '\n';   // no captures: converts
}

