// functor.cpp: an object you can call, written by hand and by the Compiler.
#include <iostream>

struct AddBonus {                        // a function object (functor)
    int bonus;                           // its "capture"
    int operator()(int x) const { return x + bonus; }
};

int main() {
    AddBonus by_hand{10};
    int bonus{10};
    auto by_lambda = [bonus](int x) { return x + bonus; };   // the Compiler writes a class like AddBonus

    std::cout << by_hand(5) << ' ' << by_lambda(5) << '\n';
    std::cout << sizeof(by_hand) << ' ' << sizeof(by_lambda) << '\n';   // same shape, same size
}

