// lambda_parts.cpp: every part of a lambda, from shortest to longest.
#include <iostream>

int main() {
    auto hello = [] { std::cout << "hello\n"; };          // capture list and body only
    auto twice = [](int x) { return x * 2; };             // + a parameter
    auto half = [](int x) -> double { return x / 2.0; };  // + a written return type
    int bonus{10};
    auto add_bonus = [bonus](int x) { return x + bonus; };  // + a capture

    hello();
    std::cout << twice(21) << '\n';
    std::cout << half(7) << '\n';
    std::cout << add_bonus(5) << '\n';
    std::cout << [](int a, int b) { return a * b; }(6, 7) << '\n';   // made and called at once
}

