// remote_shelf.cpp: many kinds of device on one shelf, through unique_ptr<Device>.
#include <iostream>
#include <memory>
#include <string>
#include <utility>
#include <vector>

class Device {
public:
    explicit Device(std::string name) : name_{std::move(name)} {}
    virtual ~Device() { std::cout << "  recycled " << name_ << '\n'; }
    virtual void play() const = 0;
protected:
    std::string name_;
};

class Tv : public Device {
public:
    using Device::Device;            // reuse Device's constructor
    void play() const override { std::cout << name_ << ": film\n"; }
};

class Radio : public Device {
public:
    using Device::Device;
    void play() const override { std::cout << name_ << ": music\n"; }
};

int main() {
    std::vector<std::unique_ptr<Device>> shelf;
    shelf.push_back(std::make_unique<Tv>("Lounge TV"));
    shelf.push_back(std::make_unique<Radio>("Kitchen radio"));
    shelf.push_back(std::make_unique<Tv>("Bedroom TV"));
    for (const auto& d : shelf) d->play();     // one button, three answers
    std::cout << "clearing the shelf\n";
    shelf.clear();                             // each unique_ptr deletes its device
    std::cout << "done\n";
}

