// sizes.cpp: the hidden pointer that virtual adds to every object.
#include <iostream>

struct Plain {                   // no virtual functions
    int volume{5};
    void play() const {}
};

struct Virtual {                 // two virtual functions: play and the destructor
    int volume{5};
    virtual void play() const {}
    virtual ~Virtual() = default;
};

struct MoreVirtual {             // three: play, stop and the destructor
    int volume{5};
    virtual void play() const {}
    virtual void stop() const {}
    virtual ~MoreVirtual() = default;
};

int main() {
    std::cout << "sizeof(int)         = " << sizeof(int) << '\n';
    std::cout << "sizeof(Plain)       = " << sizeof(Plain) << '\n';
    std::cout << "sizeof(Virtual)     = " << sizeof(Virtual) << '\n';
    std::cout << "sizeof(MoreVirtual) = " << sizeof(MoreVirtual) << '\n';
    std::cout << "sizeof(void*)       = " << sizeof(void*) << '\n';
}

