// std_function.cpp: one box that can hold any callable with the right shape.
#include <functional>
#include <iostream>
#include <string>
#include <vector>

int square(int x) { return x * x; }                       // an ordinary function

struct Times {                                            // a functor
    int k;
    int operator()(int x) const { return x * k; }
};

int main() {
    int bonus{100};
    std::vector<std::function<int(int)>> buttons;         // all take an int, return an int
    buttons.push_back(square);
    buttons.push_back(Times{3});
    buttons.push_back([bonus](int x) { return x + bonus; });
    buttons.push_back([](int x) { return -x; });
    for (const auto& b : buttons) std::cout << b(7) << ' ';
    std::cout << '\n';

    auto plain = [bonus](int x) { return x + bonus; };
    std::cout << "lambda: " << sizeof(plain) << " bytes, std::function: "
              << sizeof(std::function<int(int)>) << " bytes\n";
    std::function<int(int)> empty;
    std::cout << "empty box holds something? " << std::boolalpha << static_cast<bool>(empty) << '\n';
}

